insert into project_tech_topics (tech_topic_id, project_id, block_kind, title, summary, body_md, tech_domain, sort_order, status, confidentiality, source_kind, source_ref, source_url, needs_check, check_reason, created_by, updated_by) values ($t$ptt_sx_closed_gilsp$t$, $t$p21$t$, $t$condition$t$, $t$GILSPの判定条件と、SXの強化株で分かっていること$t$, $t$経済産業省のGILSP基準を1行ずつ置き、SXの強化株で分かっていることと確かめ先を書く。判定が変わると、手続き・処理水・審査期間がまとめて変わる。$t$, $body$強化株2はおよそ100mLの培養段階で、性能試験の前にある。耐性マーカーと増殖速度は株の作り方に依存するので、性能評価の前に確かめれば作り直しを避けられる。増殖の制限は宿主の性質で決まり、好熱性がその根拠になりうる。$body$, $t$閉鎖系（強化株）$t$, 25, $t$active$t$, $t$confidential$t$, $t$literature$t$, $t$GILSP告示（経済産業省）／SXの状況は閉鎖系レポート 1-1-1$t$, $t$https://sx-heisakei-ronten.vercel.app$t$, false, null, $t$amie$t$, $t$amie$t$);
insert into project_tech_topics (tech_topic_id, project_id, block_kind, title, summary, body_md, tech_domain, sort_order, status, confidentiality, source_kind, source_ref, source_url, needs_check, check_reason, created_by, updated_by) values ($t$ptt_sx_closed_reactor$t$, $t$p21$t$, $t$condition$t$, $t$閉鎖系リアクターに求められる設備と運用 — 今の設計で足りているか$t$, $t$カテゴリー1相当の要件を装置と運用に落とし、7/10の封じ込め設計で足りているものと足りないものに分けた。$t$, null, $t$閉鎖系（強化株）$t$, 26, $t$active$t$, $t$internal$t$, $t$literature$t$, $t$カルタヘナ法 第2条・第12条・第13条／産業利用二種省令 第3〜5条・別表／研究開発二種省令 第2条・別表第三／経済産業省・NITE「第二種使用等の手引き及び注意事項」第5.1版（令和8年9月）／SX リアクター構造・封じ込め・交換運用設計 v0.1（2026-07-10）$t$, $t$https://sx-heisakei-ronten.vercel.app$t$, false, null, $t$amie$t$, $t$amie$t$);
insert into project_tech_topics (tech_topic_id, project_id, block_kind, title, summary, body_md, tech_domain, sort_order, status, confidentiality, source_kind, source_ref, source_url, needs_check, check_reason, created_by, updated_by) values ($t$ptt_sx_closed_mechanism$t$, $t$p21$t$, $t$article$t$, $t$金属を取る仕組みと光 — 吸着と取込み、生きている・取り込む・増える$t$, $t$強化株の価値が乗るのは細胞内への取込み側。処理槽に光が要るか、細胞が消耗品になるかがここで決まる。$t$, $body$**吸着と取込みは性質が正反対**

| | 吸着（細胞の表面に結合） | 取込み（細胞の内部へ運ぶ） |
|---|---|---|
| エネルギー | 不要 | 必要 |
| 生きている必要 | なし（死菌でも進む） | あり |
| 速さ | 速い（分〜時間で頭打ち） | 遅い（時間〜日） |
| 光・二酸化炭素 | 不要 | 要る |

TmtAはメタロチオネイン、つまり細胞の中で金属を掴むタンパク質で、強化株の効果は理屈の上では取込み側に出る。9/2に報告された「強化株1が24時間で50ppmを全量取り込み、乾燥菌体重量比5.3%」は、吸着と取込みが分けて測られていない（技術検証「TmtAと鉄の結合を直接測定する」）。

**光の要否は3段階に分かれる**

| 状態 | 光は要るか | 仕組み |
|---|---|---|
| 生きている | 不要 | 光合成中に蓄えたグリコーゲンを、暗所で呼吸して使う |
| 取り込む | その場では不要。事前の蓄えが要る | 蓄えから作ったATPで輸送体を動かす。蓄えが尽きるまで続く |
| 増える | 要る | 光合成で二酸化炭素を固定する。Synechocystisはグルコースがあっても完全な暗黒では増えず、1日数分の青色光が合図として要る |

「処理槽に光は要らない」という説明は、細胞を別の工程で育てて蓄えさせてから入れる前提なら整合する。有機物を含む排液では、外から炭素とエネルギーを得られる可能性がある（未確認）。

**必要な菌体量**

必要な菌体量 ＝ 対象物質の濃度 ÷ 取り込み効率 ÷ 使い回せる回数。50ppm・強化株の5.3%・使い捨てでは、排水1m³あたり約0.94kg（乾燥重量）。共通の目安「排水1m³あたり培養液10L」（約10g）の約94倍。金額と用途別の原価はコスト試算タブが正本。

**検討して外した案** — 死菌にしてカセットにする案は採らない。TmtAは細胞内のタンパク質で、殺すと流出し、残るのは細胞壁による吸着だけになるため。$body$, $t$閉鎖系（強化株）$t$, 27, $t$active$t$, $t$confidential$t$, $t$manual$t$, $t$閉鎖系レポート 問3（吸着と取込みの文献、シアノバクテリアの暗所代謝の文献、9/2定例の試験値）$t$, $t$https://sx-heisakei-ronten.vercel.app$t$, false, null, $t$amie$t$, $t$amie$t$);
